//! The route catalog recovered from the 9.6.30 APK, embedded at build time.
//!
//! `assets/routes.json` is generated by the Python tooling
//! (`python -I tools/gen_routes.py …` in `netease_api_recovered-1.0.0`), so the
//! Rust service and the Python client describe exactly the same API surface.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

/// One canonical endpoint and the parameter keys recovered for it.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RouteInfo {
    pub route: String,
    #[serde(default)]
    pub params: Vec<String>,
    pub group: String,
    #[serde(default)]
    pub inferred: bool,
}

static RAW: &str = include_str!("../assets/routes.json");

const PREFIXES: [&str; 6] = ["api/", "weapi/", "eapi/", "xeapi/", "neapi/", "linuxapi/"];

pub struct Catalog {
    routes: HashMap<String, RouteInfo>,
    groups: HashMap<String, usize>,
}

impl Catalog {
    /// Parse the embedded catalog once per process.
    pub fn global() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG
            .get_or_init(|| Catalog::from_json(RAW).expect("embedded route catalog is valid JSON"))
    }

    pub fn from_json(raw: &str) -> Result<Self, serde_json::Error> {
        let entries: Vec<RouteInfo> = serde_json::from_str(raw)?;
        let mut routes = HashMap::with_capacity(entries.len());
        let mut groups: HashMap<String, usize> = HashMap::new();
        for entry in entries {
            *groups.entry(entry.group.clone()).or_default() += 1;
            routes.insert(entry.route.clone(), entry);
        }
        Ok(Self { routes, groups })
    }

    pub fn len(&self) -> usize {
        self.routes.len()
    }

    pub fn is_empty(&self) -> bool {
        self.routes.is_empty()
    }

    pub fn group_count(&self) -> usize {
        self.groups.len()
    }

    /// Number of routes per group, sorted by name.
    pub fn group_counts(&self) -> Vec<(String, usize)> {
        let mut out: Vec<(String, usize)> =
            self.groups.iter().map(|(g, n)| (g.clone(), *n)).collect();
        out.sort_by(|a, b| a.0.cmp(&b.0));
        out
    }

    pub fn all(&self) -> impl Iterator<Item = &RouteInfo> {
        self.routes.values()
    }

    /// Look a route up the way the Python client does: canonicalize any
    /// spelling, then accept `v1/`…`v9/` prefixed forms.
    pub fn get(&self, spelling: &str) -> Option<&RouteInfo> {
        let canonical = canonical(spelling);
        if let Some(found) = self.routes.get(&canonical) {
            return Some(found);
        }
        for version in 1..=9 {
            if let Some(found) = self.routes.get(&format!("v{version}/{canonical}")) {
                return Some(found);
            }
        }
        None
    }

    /// Case-insensitive substring search, optionally restricted to a group.
    pub fn find(&self, needle: &str, group: Option<&str>) -> Vec<&RouteInfo> {
        let needle = needle.to_lowercase();
        let mut out: Vec<&RouteInfo> = self
            .routes
            .values()
            .filter(|e| needle.is_empty() || e.route.to_lowercase().contains(&needle))
            .filter(|e| group.is_none_or(|g| e.group == g))
            .collect();
        out.sort_by(|a, b| a.route.cmp(&b.route));
        out
    }
}

/// Strip URL scheme, query, fragment and transport prefixes from a route.
pub fn canonical(route: &str) -> String {
    let mut path = route;
    if let Some((_, rest)) = path.split_once("://") {
        // Drop authority, keep path + query.
        path = rest.split_once('/').map(|(_, p)| p).unwrap_or("");
    }
    let path = path.split(['?', '#']).next().unwrap_or("");
    let mut path = path.trim_matches('/');
    for prefix in PREFIXES {
        if let Some(rest) = path.strip_prefix(prefix) {
            path = rest;
            break;
        }
    }
    path.trim_matches('/').to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_catalog_matches_the_recovered_one() {
        let catalog = Catalog::global();
        assert_eq!(catalog.len(), 1293);
        assert_eq!(catalog.group_count(), 150);
        assert!(catalog.all().any(|e| e.inferred));
        assert!(catalog.all().any(|e| !e.inferred));
    }

    #[test]
    fn canonical_strips_scheme_query_and_prefixes() {
        assert_eq!(canonical("song/detail"), "song/detail");
        assert_eq!(canonical("/api/song/detail"), "song/detail");
        assert_eq!(canonical("weapi/song/detail?x=1"), "song/detail");
        assert_eq!(
            canonical("https://music.163.com/weapi/song/detail?a=1"),
            "song/detail"
        );
        assert_eq!(canonical("eapi/v3/song/detail"), "v3/song/detail");
    }

    #[test]
    fn lookup_tolerates_prefixes_and_versions() {
        let catalog = Catalog::global();
        assert_eq!(catalog.get("song/detail").unwrap().route, "v3/song/detail");
        assert_eq!(
            catalog.get("/api/song/detail").unwrap().route,
            "v3/song/detail"
        );
        assert_eq!(
            catalog.get("eapi/song/detail?x=1").unwrap().route,
            "v3/song/detail"
        );
        assert!(catalog.get("definitely/not/a/route").is_none());
    }

    #[test]
    fn lookup_does_not_fuzzy_match_a_suffix() {
        // Regression from the Python client: "song/url" must not resolve to
        // "alarm/song/url".
        let catalog = Catalog::global();
        assert!(catalog.get("song/url").is_none());
    }

    #[test]
    fn find_is_case_insensitive_and_groupable() {
        let catalog = Catalog::global();
        let hits = catalog.find("SONG/DETAIL", None);
        assert!(hits.iter().any(|e| e.route == "v3/song/detail"));
        assert!(catalog
            .find("detail", Some("song"))
            .iter()
            .all(|e| e.group == "song"));
    }
}
